beforeExample:
package com.example;

public class MyClass {
    enum MyEnum { VALUE1, VALUE2, VALUE3 }

    public void processEnum(MyEnum e) {
        switch (e) {
            case MyEnum.VALUE1: // This should match and be fixed
                System.out.println("Value 1");
                break;
            case VALUE2: // This should not match
                System.out.println("Value 2");
                break;
            default:
                System.out.println("Other value");
        }
        // This is a valid qualified access outside a case label and should NOT match
        MyEnum val = MyEnum.VALUE3;
        System.out.println(val);
    }

    public void otherMethod() {
        // This is not an enum constant and should NOT match
        String s = System.out.toString();
    }
}

